#### player/player.gd
```
extends CharacterBody2D

@export var jump_height: float = 128.0
@export var jump_time_to_peak: float = 0.4
@export var speed: float = 200.0
@export var max_fall_speed: float = 600.0

@export_group("Tolleranze Salto")
@export var coyote_time: float = 0.15
@export var jump_buffer_time: float = 0.15

@export_group("Accelerazione e Attrito")
@export var ground_acceleration: float = 1200.0
@export var air_acceleration: float = 400.0
@export var ground_friction: float = 1000.0

var gravity: float
var jump_velocity: float

var coyote_timer: float = 0.0
var jump_buffer_timer: float = 0.0

@onready var animated_sprite: AnimatedSprite2D = $AnimatedSprite2D


func _ready() -> void:
	recalculate_physics()


func recalculate_physics() -> void:
	gravity = (2.0 * jump_height) / (jump_time_to_peak * jump_time_to_peak)
	jump_velocity = -(2.0 * jump_height) / jump_time_to_peak


func _physics_process(delta: float) -> void:
	if not is_on_floor():
		velocity.y += gravity * delta
		if velocity.y > max_fall_speed:
			velocity.y = max_fall_speed

	if is_on_floor():
		coyote_timer = coyote_time
	else:
		coyote_timer -= delta

	if Input.is_action_just_pressed("jump"):
		jump_buffer_timer = jump_buffer_time
	else:
		jump_buffer_timer -= delta

	if jump_buffer_timer > 0.0 and coyote_timer > 0.0:
		velocity.y = jump_velocity
		jump_buffer_timer = 0.0
		coyote_timer = 0.0

	if Input.is_action_just_released("jump") and velocity.y < 0.0:
		velocity.y *= 0.5

	var direction := Input.get_axis("move_left", "move_right")
	var accel := ground_acceleration if is_on_floor() else air_acceleration

	if direction != 0.0:
		velocity.x = move_toward(velocity.x, direction * speed, accel * delta)
	else:
		var decel := ground_friction if is_on_floor() else air_acceleration
		velocity.x = move_toward(velocity.x, 0.0, decel * delta)

	move_and_slide()
	update_animation(direction)


func update_animation(direction: float) -> void:
	if direction > 0.0:
		animated_sprite.flip_h = false
	elif direction < 0.0:
		animated_sprite.flip_h = true

	if is_on_floor():
		if abs(velocity.x) > 10.0:
			animated_sprite.play("run")
		else:
			animated_sprite.play("idle")
	else:
		if velocity.y < 0.0:
			animated_sprite.play("jump")
		else:
			animated_sprite.play("fall")
```

## Parte teorica della lezione (sintesi)
# La macchina a stati
Impara a strutturare la logica del personaggio usando il pattern della Macchina a Stati Finita (FSM) in Godot 4.7. Sostituirai un insieme confuso di variabili booleane con script dedicati a ogni singolo stato, rendendo il codice ordinato, pulito e facile da estendere.

Man mano che un personaggio si arricchisce di azioni (correre, saltare, cadere, scivolare, accovacciarsi), la tentazione iniziale è aggiungere tante variabili vero/falso come `is_jumping`, `is_running` o `is_crouching`. Con il passare del tempo queste variabili finiscono inevitabilmente per contraddirsi: il personaggio potrebbe risultare contemporaneamente in volo e accovacciato, generando bug difficili da isolare. Questa confusione nel codice viene chiamata in gergo *zuppa di booleani* (*boolean soup*).

La soluzione a questo disordine è la **Macchina a Stati Finita** (in inglese *Finite State Machine*, o FSM). L'idea alla base è semplice: il personaggio può trovarsi in **un solo stato alla volta** (per esempio solo *Idle*, oppure solo *Jump*). Ogni stato è responsabile unicamente di quello che succede durante la propria esecuzione: cosa fare quando vi si entra (`enter`), quando vi si esce (`exit`), come aggiornare la fisica (`physics_update`) e verso quale altro stato passare.

In Godot 4.7 realizziamo la macchina a stati sfruttando l'albero dei nodi e l'ereditarietà. Creiamo prima di tutto una **classe base comune** chiamata `State`, che estende il nodo generale `Node`. Questa classe definisce l'interfaccia standard con le funzioni vuote che ogni singolo stato andrà a personalizzare. L'istruzione `class_name State` rende il tipo `State` disponibile in tutto il progetto.

```gdscript
class_name State
extends Node

## Segnale emesso quando lo stato richiede di passare a un nuovo stato.
signal transitioned(state: State, new_state_name: String)


## Chiamata quando si entra in questo stato.
func enter() -> void:
	pass


## Chiamata quando si esce da questo stato.
func exit() -> void:
	pass


## Chiamata ad ogni fotogramma di processo (opzionale).
func update(_delta: float) -> void:
	pass


## Chiamata ad ogni fotogramma di fisica.
func physics_update(_delta: float) -> void:
	pass
```

Per gestire il passaggio tra i vari stati ci serve un nodo contenitore chiamato `StateMachine`. Questo nodo raccoglie tutti i nodi di stato figli, mantiene il riferimento allo stato attualmente attivo in una variabile `current_state` e gli inoltra gli aggiornamenti di fisica ad ogni fotogramma.

```gdscript
class_name StateMachine
extends Node

@export var initial_state: State

var current_state: State
var states: Dictionary = {}


func _ready() -> void:
	await owner.ready
	for child in get_children():
		if child is State:
			states[child.name.to_lower()] = child
			child.transitioned.connect(_on_child_transitioned)

	if initial_state:
		initial_state.enter()
		current_state = initial_state


func _process(delta: float) -> void:
	if current_state:
		current_state.update(delta)


func _physics_process(delta: float) -> void:
	if current_state:
		current_state.physics_update(delta)


func _on_child_transitioned(state: State, new_state_name: String) -> void:
	if state != current_state:
		return

	var new_state: State = states.get(new_state_name.to_lower())
	if not new_state:
		return

	if current_state:
		current_state.exit()

	new_state.enter()
	current_state = new_state
```

Organizzare i nodi di stato nella scena del personaggio
1. Apri la scena del personaggio `res://player/player.tscn` nell'area di lavoro 2D.
2. Nel pannello *Scene*, seleziona il nodo radice `Player`, premi **+** per aggiungere un nodo `Node`, rinominalo in `StateMachine` e assegnagli lo script `res://player/state_machine.gd`.
3. Seleziona il nodo `StateMachine`, premi **+** per aggiungere un figlio `Node`, rinominalo in `Idle` e collega lo script `res://player/player_idle_state.gd`.
4. Nel pannello *Inspector*, seleziona il nodo `StateMachine` e assegna alla proprietà `Initial State` il nodo figlio `Idle`.

Ora possiamo implementare lo script specifico per lo stato fermo (`PlayerIdleState`). Questo stato si occupa esclusivamente di ciò che avviene quando il personaggio è fermo a terra: attiva l'animazione `idle` all'entrata e controlla se la pressione dei tasti o la gravità richiedono un passaggio verso `run`, `jump`, `fall` o `crouch`.

```gdscript
class_name PlayerIdleState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("idle")


func physics_update(_delta: float) -> void:
	if not player.is_on_floor():
		transitioned.emit(self, "fall")
		return

	if Input.is_action_just_pressed("jump"):
		transitioned.emit(self, "jump")
		return

	var direction := Input.get_axis("move_left", "move_right")
	if direction != 0.0:
		transitioned.emit(self, "run")
		return

	if Input.is_action_pressed("crouch"):
		transitioned.emit(self, "crouch")
		return
```

Il vero vantaggio della Macchina a Stati si manifesta quando vogliamo aggiungere una nuova meccanica, come lo stato **accovacciato** (`Crouch`). Senza la FSM dovremmo modificare il codice principale aggiungendo nuovi controlli `if`. Con la FSM ci basta creare un nuovo file di script `PlayerCrouchState` e aggiungere un nodo `Crouch` sotto `StateMachine`, senza dover toccare la logica interna degli altri stati.

```gdscript
class_name PlayerCrouchState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("idle")
	player.velocity.x = 0.0


func physics_update(_delta: float) -> void:
	if not player.is_on_floor():
		transitioned.emit(self, "fall")
		return

	if not Input.is_action_pressed("crouch"):
		var direction := Input.get_axis("move_left", "move_right")
		if direction != 0.0:
			transitioned.emit(self, "run")
		else:
			transitioned.emit(self, "idle")
```

Riepilogo:
- La Macchina a Stati Finita (FSM) isola i comportamenti del personaggio garantendo che solo uno stato sia attivo alla volta.
- La classe base `State` definisce le funzioni standard (`enter`, `exit`, `physics_update`) sovrascritte dai singoli stati.
- Il nodo `StateMachine` gestisce lo stato corrente, esegue l'aggiornamento della fisica e gestisce i cambi di stato tramite il segnale `transitioned`.
- Aggiungere nuove azioni (come accovacciarsi) richiede solo di creare un nuovo script di stato, senza rischiare di rompere il codice esistente.

## Cosa sa già fare (lezioni precedenti)
Lezioni più vicine (in dettaglio):
- Progetto «Arena» – tappa 2: nemici e ondate: Tre tipi di nemico descritti come Resource, ondate descritte come dati, nemici che nascono ai bordi e inseguono. (concetti: )
- Progetto «Arena» – tappa 3: esperienza e potenziamenti: I nemici lasciano esperienza; a fine ondata il gioco si ferma e propone tre potenziamenti a caso tra almeno otto; gli effetti si sommano. (concetti: )
- Progetto «Arena» – tappa 4: gioco completo: Menu, pausa, fine partita con record salvato, suoni e musica, cento nemici insieme senza scatti, esportazione per Windows. (concetti: )
- Gravità e salto: Impara a gestire la gravità e la logica di salto per un personaggio 2D in Godot 4.7. Scoprirai come calcolare la gravità e la spinta verso l'alto a partire dall'altezza e dal tempo di risalita desiderati, e come realizzare un salto variabile che risponde alla pressione del tasto. (concetti: Gravità come accelerazione costante in _physics_process(), Rilevamento del terreno tramite is_on_floor(), Calcolo cinematico di gravità e spinta (altezza e durata del salto), Salto variabile (cut jump) al rilascio del tasto di input)
- Un salto che perdona: Impara ad aggiungere Coyote Time, Jump Buffer e accelerazione differenziata tra terra e aria in Godot 4.7. Scoprirai come calibrare i controlli per rendere il salto reattivo, naturale e tollerante verso le imprecisioni del giocatore. (concetti: Coyote Time per saltare subito dopo aver lasciato una piattaforma, Jump Buffer per registrare l'input prima di toccare il suolo, Inerzia e accelerazione orizzontale con move_toward(), Controllo d'aria ridotto (air acceleration) rispetto al terreno, Calibrazione dei parametri fisici tramite le proprietà esportate)
- Animazioni a fotogrammi: Impara ad animare il personaggio di un gioco a piattaforme 2D in Godot 4.7 usando AnimatedSprite2D e la risorsa SpriteFrames. Scoprirai come ritagliare le animazioni da un foglio di immagini, orientare lo sprite nella direzione del movimento e scegliere l'animazione corretta in base allo stato fisico del personaggio. (concetti: AnimatedSprite2D e la risorsa SpriteFrames, Estrazione di fotogrammi da uno sprite sheet, Orientamento dello sprite tramite la proprietà flip_h, Selezione dinamica dell'animazione in base a is_on_floor() e alla velocità)

