var is_patrolling: bool = true
var is_chasing: bool = false
var is_moving_right: bool = true


func _physics_process(delta: float) -> void:
	if is_patrolling:
		if is_moving_right:
			velocity.x = speed
			if position.x >= patrol_right_limit:
				is_moving_right = false
		else:
			velocity.x = -speed
			if position.x <= patrol_left_limit:
				is_moving_right = true
		if target and position.distance_to(target.position) < 100.0:
			is_patrolling = false
			is_chasing = true
	elif is_chasing:
		if target:
			var dir := (target.position - position).normalized()
			velocity = dir * speed
			if position.distance_to(target.position) >= 150.0:
				is_chasing = false
				is_patrolling = true
	move_and_slide()
